import { Controller } from "@hotwired/stimulus"
import { formatDateTime, formatFullDateAndTime, parseDateTime } from "helpers/date_helpers"

const REFRESH_INTERVAL = 60_000 // 1 minute (in milliseconds)

// Turns the raw timestamp the server rendered in a <time datetime="…"> element
// into words in the viewer's timezone. Relative wordings ("2 hours ago") are
// kept fresh while the page stays open, and get the full date as a tooltip.
export default class extends Controller {
  static values = { format: { type: String, default: "relative" } }

  #timer
  #rerender = this.render.bind(this)

  connect() {
    this.render()

    document.addEventListener("turbo:morph", this.#rerender)
    if (this.#relative) this.#timer = setInterval(this.#rerender, REFRESH_INTERVAL)
  }

  disconnect() {
    document.removeEventListener("turbo:morph", this.#rerender)
    clearInterval(this.#timer)
  }

  render() {
    this.element.textContent = formatDateTime(this.#date, this.formatValue)

    if (this.#relative && !this.element.title) {
      this.element.title = formatFullDateAndTime(this.#date)
    }
  }

  get #date() {
    return parseDateTime(this.element.getAttribute("datetime"))
  }

  get #relative() {
    return [ "relative", "time_ago" ].includes(this.formatValue)
  }
}
